import java.io.BufferedInputStream

private const val MOD = 998244353L

private class FastScanner {
    private val input = BufferedInputStream(System.`in`)
    private val buffer = ByteArray(1 shl 16)
    private var length = 0
    private var pointer = 0

    private fun readByte(): Int {
        if (pointer >= length) {
            length = input.read(buffer)
            pointer = 0
            if (length <= 0) return -1
        }
        return buffer[pointer++].toInt()
    }

    fun nextLong(): Long {
        var c: Int
        do {
            c = readByte()
        } while (c <= 32)

        var value = 0L
        while (c > 32) {
            value = value * 10 + (c - '0'.code)
            c = readByte()
        }
        return value
    }
}

private fun modPow(baseValue: Long, exponentValue: Long): Long {
    var base = baseValue % MOD
    var exponent = exponentValue
    var result = 1L

    while (exponent > 0) {
        if ((exponent and 1L) != 0L) {
            result = result * base % MOD
        }
        base = base * base % MOD
        exponent = exponent shr 1
    }
    return result
}

fun main() {
    val fs = FastScanner()
    val n = fs.nextLong().toInt()
    val k = fs.nextLong().toInt()
    val l = fs.nextLong() % MOD

    val limit = 2 * n + 1
    val factorial = LongArray(limit + 1)
    val inverseFactorial = LongArray(limit + 1)

    factorial[0] = 1L
    for (i in 1..limit) {
        factorial[i] = factorial[i - 1] * i % MOD
    }

    inverseFactorial[limit] = modPow(factorial[limit], MOD - 2)
    for (i in limit downTo 1) {
        inverseFactorial[i - 1] = inverseFactorial[i] * i % MOD
    }

    fun combination(a: Int, b: Int): Long {
        if (b < 0 || b > a) return 0L
        return factorial[a] * inverseFactorial[b] % MOD *
                inverseFactorial[a - b] % MOD
    }

    val powersOfTwo = LongArray(n + 1)
    powersOfTwo[0] = 1L
    for (i in 1..n) {
        powersOfTwo[i] = powersOfTwo[i - 1] * 2L % MOD
    }

    var sum = 0L
    for (covered in k..n) {
        val remaining = n - covered
        val outer = combination(n, covered) * powersOfTwo[covered] % MOD

        var inner = 0L
        for (a in 0..remaining) {
            val leftExponent = 2 * a + covered
            val rightExponent = 2 * n - covered - 2 * a

            var term = combination(remaining, a)
            term = term * factorial[leftExponent] % MOD
            term = term * factorial[rightExponent] % MOD
            inner += term
            if (inner >= MOD) inner -= MOD
        }

        sum = (sum + outer * inner) % MOD
    }

    val answer = sum * inverseFactorial[2 * n + 1] % MOD * l % MOD
    print(answer)
}

